const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');
menu.addEventListener('click',()=>{const state=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!state));nav.classList.toggle('open',!state)});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}));
const journeys={parcial:['Aprendizado em um turno.','Uma opção para famílias que procuram a vivência escolar em parte do dia, com tempo para outras experiências fora da escola.'],semi:['Um pouco mais de tempo, novas possibilidades.','Uma alternativa entre a jornada parcial e a integral. Converse com a escola para conhecer os horários e a organização da rotina para a etapa da criança.'],integral:['Cuidado e aprendizado ao longo do dia.','Uma jornada ampliada para famílias que precisam conciliar a rotina com o tempo na escola. Conheça com a equipe os momentos, as atividades e a alimentação previstos para cada turma.']};
const tabs=[...document.querySelectorAll('[data-journey]')];function selectTab(t){tabs.forEach(b=>{b.setAttribute('aria-selected',String(b===t));b.tabIndex=b===t?0:-1});const panel=document.querySelector('#journey'),data=journeys[t.dataset.journey];panel.setAttribute('aria-labelledby',t.id);panel.querySelector('h3').textContent=data[0];panel.querySelector('p').textContent=data[1]}
tabs.forEach((t,i)=>{t.addEventListener('click',()=>selectTab(t));t.addEventListener('keydown',e=>{let j;if(e.key==='ArrowRight')j=(i+1)%tabs.length;if(e.key==='ArrowLeft')j=(i+tabs.length-1)%tabs.length;if(e.key==='Home')j=0;if(e.key==='End')j=tabs.length-1;if(j!==undefined){e.preventDefault();selectTab(tabs[j]);tabs[j].focus()}})});
const dialog=document.querySelector('#media-dialog'),content=document.querySelector('#media-content');let opener;
function openMedia(button){opener=button;content.replaceChildren();if(button.dataset.photo){const img=new Image();img.src=button.dataset.photo;img.alt=button.dataset.caption;content.append(img);const p=document.createElement('p');p.textContent=button.dataset.caption;content.append(p)}else{const video=document.createElement('video');video.src=button.dataset.video;video.controls=true;video.playsInline=true;video.preload='metadata';content.append(video);video.addEventListener('error',()=>{const p=document.createElement('p');p.textContent='Não foi possível carregar o vídeo. Tente novamente em instantes.';content.append(p)},{once:true})}dialog.showModal();const playing=content.querySelector("video");if(playing){playing.setAttribute("aria-label",button.querySelector("b")?.textContent||"Relato em vídeo");playing.play().catch(()=>{})}}
document.querySelectorAll('[data-photo],[data-video]').forEach(b=>b.addEventListener('click',()=>openMedia(b)));
dialog.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{const v=content.querySelector('video');if(v)v.pause();content.replaceChildren();opener?.focus()});
const form=document.querySelector('#visit-form');if(form)form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const body=`Olá, equipe da Escola O Verbo!\n\nGostaria de conhecer a escola e consultar as matrículas para 2027.\n\nResponsável: ${data.get('responsavel')}\nE-mail de contato: ${data.get('contato')}\nEtapa de interesse: ${data.get('etapa')}\nJornada desejada: ${data.get('jornada')}\n\nPodemos conversar sobre uma visita?`;window.location.href='mailto:escolaoverbo@hotmail.com?subject='+encodeURIComponent('Solicitação de visita — Matrículas 2027')+'&body='+encodeURIComponent(body);form.querySelector('.form-status').textContent='Mensagem preparada para o seu aplicativo de e-mail. Revise e confirme o envio por lá. Se ele não abrir, ligue para (82) 3024-6212.'});
